def verify_snapshot():
    for item in json.loads((cache / 'repo-snapshot-manifest.json').read_text()):
        file = export / item['path']
        if 'symlink' in item:
            if not file.is_symlink() or os.readlink(file) != item['symlink']:
                raise SystemExit('Snapshot symlink changed: ' + item['path'])
        else:
            digest = checksum_file(file)
            if digest != item['sha256']:
                raise SystemExit('Snapshot bytes changed: ' + item['path'])
